<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/css/design.css"><title>Bookings</title></head><body class="dashboard-page"><header class="dashboard-header"><a href="/">SUN SON SOLAR</a><span><?= esc(session()->get('name')) ?></span><a href="/logout">Logout</a></header><main class="section"><h1>Booking Management</h1><?php foreach($bookings as $b):?><div class="card"><h3><?= esc($b['FirstName'].' '.$b['LastName']) ?> · <?= esc($b['service_type']) ?></h3><p><?= esc($b['preferred_date']) ?> · <?= esc($b['status']) ?></p><form method="post" action="/admin/bookings/update/<?= $b['id'] ?>"><?= csrf_field() ?><label>Status</label><select name="status"><option>Approved</option><option>Declined</option><option>Scheduled</option><option>Completed</option></select><label>Assign Technician</label><select name="technician_id"><option value="">Unassigned</option><?php foreach($technicians as $t):?><option value="<?= $t['id'] ?>"><?= esc($t['FirstName'].' '.$t['LastName']) ?></option><?php endforeach;?></select><label>Notes</label><input name="admin_notes"><button class="button primary">Save</button></form></div><?php endforeach;?></main><script src="/js/main.js"></script></body></html>